function setupSheet(sheet) {
  if (sheet.getLastRow() === 0) {
    var headers = [
      "ID", "Дата", "Категория ID", "Категория", "Название", "Сумма (₽)", 
      "Кто оплатил", "Доля Мамы (₽)", "Доля Папы (₽)", "Статус", "Заметка", "Создано", "Обновлено"
    ];
    sheet.appendRow(headers);
    
    var headerRange = sheet.getRange(1, 1, 1, headers.length);
    headerRange.setBackground("#15803d");
    headerRange.setFontColor("#ffffff");
    headerRange.setFontWeight("bold");
    headerRange.setHorizontalAlignment("center");
    sheet.setFrozenRows(1);
  }
}

function doGet(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getActiveSheet();
    setupSheet(sheet);
    
    var lastRow = sheet.getLastRow();
    if (lastRow <= 1) {
      return ContentService.createTextOutput(JSON.stringify({ 
        success: true, 
        expenses: [],
        rowsCount: 0,
        message: "Таблица пуста" 
      })).setMimeType(ContentService.MimeType.JSON);
    }
    
    var data = sheet.getRange(2, 1, lastRow - 1, 13).getValues();
    var expenses = [];
    
    for (var i = 0; i < data.length; i++) {
      var row = data[i];
      var id = String(row[0] || "");
      if (!id) continue;
      
      expenses.push({
        id: id,
        date: String(row[1] || ""),
        category: String(row[2] || "other"),
        title: String(row[4] || ""),
        amount: Number(row[5] || 0),
        paidBy: String(row[6] || "").toLowerCase().indexOf("мам") !== -1 ? "mom" : "dad",
        momShare: Number(row[7] || 0),
        dadShare: Number(row[8] || 0),
        status: String(row[9] || "unpaid"),
        note: String(row[10] || ""),
        createdAt: Number(row[11]) || new Date().getTime(),
        syncedWithSheet: true
      });
    }
    
    return ContentService.createTextOutput(JSON.stringify({ 
      success: true, 
      expenses: expenses,
      rowsCount: expenses.length,
      status: "online" 
    })).setMimeType(ContentService.MimeType.JSON);
    
  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ 
      success: false, 
      error: error.toString() 
    })).setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getActiveSheet();
    setupSheet(sheet);
    
    var data = JSON.parse(e.postData.contents);
    var action = data.action;
    
    if (action === "add_expense") {
      var exp = data;
      sheet.appendRow([
        exp.id,
        exp.date,
        exp.category || "other",
        exp.categoryLabel || exp.category,
        exp.title,
        exp.amount,
        exp.paidBy === "mom" ? "Мама" : "Папа",
        exp.momShare,
        exp.dadShare,
        exp.status || "unpaid",
        exp.note || "",
        exp.createdAt || new Date().getTime(),
        new Date().toLocaleString("ru-RU")
      ]);
      return ContentService.createTextOutput(JSON.stringify({ 
        success: true, 
        message: "Трата добавлена" 
      })).setMimeType(ContentService.MimeType.JSON);
    }
    
    if (action === "update_status") {
      var lastRow = sheet.getLastRow();
      if (lastRow > 1) {
        var ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
        for (var i = 0; i < ids.length; i++) {
          if (String(ids[i][0]) === String(data.id)) {
            var rowIndex = i + 2;
            sheet.getRange(rowIndex, 10).setValue(data.status || "unpaid"); // Статус
            sheet.getRange(rowIndex, 13).setValue(new Date().toLocaleString("ru-RU")); // Обновлено
            break;
          }
        }
      }
      return ContentService.createTextOutput(JSON.stringify({ 
        success: true, 
        message: "Статус обновлен" 
      })).setMimeType(ContentService.MimeType.JSON);
    }

    if (action === "delete_expense") {
      var lastRow = sheet.getLastRow();
      if (lastRow > 1) {
        var ids = sheet.getRange(2, 1, lastRow - 1, 1).getValues();
        for (var i = 0; i < ids.length; i++) {
          if (String(ids[i][0]) === String(data.id)) {
            sheet.deleteRow(i + 2);
            break;
          }
        }
      }
      return ContentService.createTextOutput(JSON.stringify({ 
        success: true, 
        message: "Трата удалена" 
      })).setMimeType(ContentService.MimeType.JSON);
    }
    
    if (action === "sync_expenses" && Array.isArray(data.expenses)) {
      // Полная синхронизация: очищаем и перезаписываем строки трат
      var lastRow = sheet.getLastRow();
      if (lastRow > 1) {
        sheet.deleteRows(2, lastRow - 1);
      }
      data.expenses.forEach(function(item) {
        sheet.appendRow([
          item.id,
          item.date,
          item.category || "other",
          item.categoryLabel || item.category,
          item.title,
          item.amount,
          item.paidBy === "mom" ? "Мама" : "Папа",
          item.momShare,
          item.dadShare,
          item.status || "unpaid",
          item.note || "",
          item.createdAt || new Date().getTime(),
          new Date().toLocaleString("ru-RU")
        ]);
      });
      return ContentService.createTextOutput(JSON.stringify({ 
        success: true, 
        message: "Синхронизировано " + data.expenses.length + " трат" 
      })).setMimeType(ContentService.MimeType.JSON);
    }
    
    return ContentService.createTextOutput(JSON.stringify({ 
      success: false, 
      error: "Неизвестное действие: " + action 
    })).setMimeType(ContentService.MimeType.JSON);
    
  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ 
      success: false, 
      error: error.toString() 
    })).setMimeType(ContentService.MimeType.JSON);
  }
}
